  title('**** TEXT (MODLIST) ****');
  const t037 = require('./ebcdic').codePage('037').fromEbcdic;
  const pr = (c) => (c < 0x20 || (c >= 0x7f && c < 0xa0) ? '.' : String.fromCharCode(c));
