      const rowNum = t.tdTop + s.tbRow;
      if (rowNum > t.rows.length) continue;
      if (!byRow.has(rowNum)) byRow.set(rowNum, new Map());
      byRow.get(rowNum).set(s.field.name, panel.convertInput(s.text.join(''), s.attr));
