  if (padc !== undefined) {
    const p = String(padc).trim();
    if (p.toUpperCase() === 'USER') r.padUser = true;
    else r.pad = unquote(p)[0] || ' ';
    r.padc = true;
  }
  const j = g('JUST');
  if (j) r.just = j[0];
  if (g('SKIP') === 'OFF') r.skip = false;
  if (g('NUMERIC') === 'ON') r.numeric = true;
  if (g('PAS') === 'ON') r.pas = true;
  if (g('NOJUMP') === 'ON') r.nojump = true;
  if (g('PASSWD') === 'ON') r.nondisplay = true;
