  if (s[0] === 0x50 && s[1] === 0x4b) return 'Zip';
  if (s.length >= 5 && s[0] === 0x02 && ebcdic(s.subarray(1, 4)) === 'ESD') return 'Obj';
  if (String(recfm).startsWith('U')) return 'Lmod';
