// ------------------------------------------------------------------------------------------
// Listing (BROWSE of an archive)
// ------------------------------------------------------------------------------------------
function listing(zip, title = '') {
  const pad2 = (n) => String(n).padStart(2, '0');
  const fmt = (d) => (d ? `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}` : ''.padEnd(16));
  const out = [];
  if (title) out.push(title);
  const enc = [...new Set(zip.entries.filter(e => e.encrypted).map(e => e.encryption))];
  out.push(`${zip.entries.length} entries` + (enc.length ? `, encrypted (${enc.join(', ')}): UNZIP asks for the password` : ''));
  if (zip.comment) out.push('Comment: ' + zip.comment);
  out.push('');
  out.push(`${'Size'.padStart(12)}  ${'Compressed'.padStart(12)}  ${'Ratio'.padStart(5)}  ${'Method'.padEnd(8)}  ${'Encryption'.padEnd(10)}  ${'Modified'.padEnd(16)}  Name`);
  out.push('-'.repeat(100));
  let tu = 0, tc = 0;
  for (const e of zip.entries) {
    tu += e.size; tc += e.csize;
    const ratio = e.size > 0 && !e.isDir ? Math.max(0, Math.round(100 - (100 * e.csize) / e.size)) + '%' : '';
    out.push(`${(e.isDir ? '<DIR>' : String(e.size)).padStart(12)}  ${(e.isDir ? '' : String(e.csize)).padStart(12)}  ${ratio.padStart(5)}  ` +
      `${(e.isDir ? '' : e.methodName).padEnd(8)}  ${e.encryption.padEnd(10)}  ${fmt(e.mtime)}  ${e.name}`);
  }
  out.push('-'.repeat(100));
  const ratio = tu > 0 ? Math.max(0, Math.round(100 - (100 * tc) / tu)) + '%' : '';
  out.push(`${String(tu).padStart(12)}  ${String(tc).padStart(12)}  ${ratio.padStart(5)}  ${zip.entries.filter(e => !e.isDir).length} file(s)`);
  return out;
}

module.exports = { isZip, isZipFile, openZip, extractAll, createZip, listing, crc32, ZipPasswordError, ZipCrypto, aesCtr };

